      default() {
        return true;
      },
    },
    showHotAndTime: {
      type: Boolean,
      default() {
        return true;
      },
    },
  },
  data() {
    return {
      keywords: ['高速', '第三代', '半导体'], // 需要高亮的关键词
    };
  },
  computed: {
    pageCode() {
      return pageCode;
